#!/usr/bin/env python3
from pathlib import Path

data = Path('/root/lab/show_ip_interface_brief.txt').read_text().splitlines()
for line in data[1:]:
    parts = line.split()
    if len(parts) >= 6:
        interface, ip, status, protocol = parts[0], parts[1], parts[-2], parts[-1]
        print(f'{interface},{ip},{status},{protocol}')

