#!/usr/bin/env python3
import json
from pathlib import Path

data = json.loads(Path('/root/lab/api/devices.json').read_text())
for dev in data['devices']:
    print(f"{dev['hostname']} ansible_host={dev['mgmt_ip']} platform={dev['platform']}")

vars.find_down_interfaces_py:
#!/usr/bin/env python3
import json
from pathlib import Path

data = json.loads(Path('/root/lab/api/interfaces.json').read_text())
for intf in data['interfaces']:
    if intf['status'] != 'up' or intf['protocol'] != 'up':
        print(f"{intf['device']} {intf['name']} {intf['status']}/{intf['protocol']} {intf['description']}")

